 85	flags: packed struct {
 86	    /// This is true when a blinking cursor should be visible and false
 87	    /// when it should not be visible. This is toggled on a timer by the
 88	    /// thread automatically.
 89	    cursor_blink_visible: bool = false,
 90	
 91	    /// This is true when the inspector is active.
 92	    has_inspector: bool = false,
 93	
 94	    /// This is true when the view is visible. This is used to determine
